28: /// A failure validating the JSON-RPC `initialize` handshake line. Kept as a
29: /// typed enum so the pure [`validate_handshake`] helper is unit-testable
30: /// without touching stdin.
31: #[derive(Debug)]
32: enum HandshakeError {
33:     /// The line was not valid JSON.
34:     Malformed(String),
35:     /// A required field was absent.
36:     MissingField(&'static str),
37:     /// The `method` field was not `"initialize"`.
38:     WrongMethod(String),
39:     /// `params.protocolVersion` did not equal the harness protocol version.
40:     VersionMismatch { expected: String, got: String },
41: }
42: 
43: impl HandshakeError {
44:     /// Human-readable message embedded in the JSON-RPC `error` object.
45:     fn message(&self) -> String {
46:         match self {
47:             HandshakeError::Malformed(e) => format!("malformed handshake JSON: {e}"),
48:             HandshakeError::MissingField(f) => format!("missing required field {f:?}"),
49:             HandshakeError::WrongMethod(m) => {
50:                 format!("expected method \"initialize\", got {m:?}")
51:             }
52:             HandshakeError::VersionMismatch { expected, got } => {
53:                 format!("protocolVersion mismatch: expected {expected:?}, got {got:?}")
54:             }
55:         }
56:     }
57: }
58: 
59: /// Validate the JSON-RPC `initialize` handshake line (pure; no I/O).
60: ///
61: /// The protocol version is cross-checked against
62: /// [`openbuff_workspace_harness::workspace_protocol_version`] dynamically, so a
63: /// harness bump moves this check with it instead of pinning a stale copy.
64: fn validate_handshake(line: &str) -> Result<(), HandshakeError> {
65:     let value: serde_json::Value =
66:         serde_json::from_str(line.trim()).map_err(|e| HandshakeError::Malformed(e.to_string()))?;
67: 
68:     let method = value
69:         .get("method")
70:         .and_then(|m| m.as_str())
71:         .ok_or(HandshakeError::MissingField("method"))?;
72:     if method != "initialize" {
73:         return Err(HandshakeError::WrongMethod(method.to_string()));
74:     }
75: 
76:     let got = value
77:         .get("params")
78:         .and_then(|p| p.get("protocolVersion"))
79:         .and_then(|p| p.as_str())
80:         .ok_or(HandshakeError::MissingField("params.protocolVersion"))?;
81: 
82:     let expected = openbuff_workspace_harness::workspace_protocol_version().to_string();
83:     if got != expected.as_str() {
84:         return Err(HandshakeError::VersionMismatch {
85:             expected,
86:             got: got.to_string(),
87:         });
88:     }
89: 
90:     Ok(())
91: }
92: 
93: /// The JSON-RPC success response line (no trailing newline; the caller adds
94: /// one). Pure so it is unit-testable without stdin/stdout.
95: fn handshake_response_line() -> String {
96:     let protocol = openbuff_workspace_harness::workspace_protocol_version().to_string();
97:     serde_json::json!({
98:         "jsonrpc": "2.0",
99:         "id": 1,
100:         "result": { "protocolVersion": protocol },
101:     })
102:     .to_string()
103: }
104: 
105: /// The JSON-RPC error response line for a failed handshake.
106: fn handshake_error_line(err: &HandshakeError) -> String {
107:     serde_json::json!({
108:         "jsonrpc": "2.0",
109:         "id": 1,
110:         "error": { "code": -32600, "message": err.message() },
111:     })
112:     .to_string()
113: }
114: 
115: /// Write one newline-terminated line to stdout and flush.
116: fn write_line(line: &str) {
117:     let stdout = std::io::stdout();
118:     let mut handle = stdout.lock();
119:     let _ = writeln!(handle, "{line}");
120:     let _ = handle.flush();
121: }
122: 
123: /// Emit a `{"ok":false,"error":"<msg>"}` envelope to stdout and exit 1. Used
124: /// for non-handshake pre-exec failures (EOF, malformed plan).
125: fn fail(msg: &str) -> ! {
126:     write_line(&serde_json::json!({ "ok": false, "error": msg }).to_string());
127:     process::exit(1);
128: }
