130: /// Drive the `exec` role end-to-end. Never returns: it either `exec`s the
131: /// target process or `process::exit`s on failure.
132: pub fn run() -> ! {
133:     let stdin = std::io::stdin();
134:     let mut reader = stdin.lock();
135: 
136:     // Phase 1: handshake.
137:     let mut handshake = String::new();
138:     match reader.read_line(&mut handshake) {
139:         Ok(0) => fail("EOF reading handshake line"),
140:         Ok(_) => {}
141:         Err(e) => fail(&format!("error reading handshake line: {e}")),
142:     }
143:     if let Err(err) = validate_handshake(&handshake) {
144:         write_line(&handshake_error_line(&err));
145:         process::exit(1);
146:     }
147:     write_line(&handshake_response_line());
148: 
149:     // Phase 2: ExecPlan.
150:     let mut plan_line = String::new();
151:     match reader.read_line(&mut plan_line) {
152:         Ok(0) => fail("EOF reading ExecPlan line"),
153:         Ok(_) => {}
154:         Err(e) => fail(&format!("error reading ExecPlan line: {e}")),
155:     }
156:     let plan: ExecPlan = match serde_json::from_str(plan_line.trim()) {
157:         Ok(p) => p,
158:         Err(e) => fail(&format!("malformed ExecPlan JSON: {e}")),
159:     };
160: 
161:     runner::run_exec(&plan)
162: }
