1: //! Builds and `exec`s the target process described by an [`ExecPlan`].
2: //!
3: //! On Linux the Landlock ruleset is applied to THIS process first (see
4: //! [`super::landlock_fs`]); the subsequent `exec` inherits those restrictions.
5: //! We never fork — order matters: restrict, then `exec`.
6: 
7: use std::io::Write;
8: use std::process::{self, Command};
9: 
10: use super::plan::ExecPlan;
11: 
12: /// Execute the plan, replacing the current process image on success.
13: ///
14: /// Diverges: on unix a successful `exec` never returns; any error path emits a
15: /// one-line `{"ok":false,"error":...}` envelope to stdout and `process::exit(1)`.
16: pub fn run_exec(plan: &ExecPlan) -> ! {
17:     // `mut`/mutation only happens on Linux; keep the binding uniform across
18:     // targets without a spurious `unused_mut` warning elsewhere.
19:     #[allow(unused_mut)]
20:     let mut enforced = false;
21: 
22:     #[cfg(target_os = "linux")]
23:     if !plan.no_landlock {
24:         enforced = super::landlock_fs::apply_fs_ruleset(plan)
25:             .unwrap_or_else(|e| fail(&format!("landlock error: {e}")));
26:     }
27: 
28:     // Pre-exec status line to STDERR; stdout is reserved for JSON-RPC frames.
29:     eprintln!("{}", status_line(enforced));
30: 
31:     let mut command = Command::new(&plan.cmd);
32:     command.args(&plan.args);
33:     if let Some(env) = &plan.env {
34:         command.env_clear();
35:         for (key, value) in env {
36:             command.env(key, value);
37:         }
38:     }
39: 
40:     exec_command(command)
41: }
42: 
43: /// Build the pre-exec status line JSON. Pure so it is unit-testable without
44: /// applying a ruleset or execing.
45: fn status_line(enforced: bool) -> String {
46:     serde_json::json!({
47:         "ok": true,
48:         "landlock": enforced,
49:         "degraded": !enforced,
50:     })
51:     .to_string()
52: }
53: 
54: /// Emit a `{"ok":false,"error":"<msg>"}` envelope to stdout and exit 1.
55: fn fail(msg: &str) -> ! {
56:     let line = serde_json::json!({ "ok": false, "error": msg }).to_string();
57:     let stdout = std::io::stdout();
58:     let mut handle = stdout.lock();
59:     let _ = writeln!(handle, "{line}");
60:     let _ = handle.flush();
61:     process::exit(1);
62: }
63: 
64: #[cfg(unix)]
65: fn exec_command(mut command: Command) -> ! {
66:     use std::os::unix::process::CommandExt;
67:     // `exec` only returns on failure (success replaces the process image), so
68:     // everything after it is the error path.
69:     let err = command.exec();
70:     fail(&format!("exec failed: {err}"));
71: }
72: 
73: #[cfg(not(unix))]
74: fn exec_command(mut command: Command) -> ! {
75:     // No `exec`-replace on non-unix: spawn, wait, and forward the exit code.
76:     match command.status() {
77:         Ok(status) => process::exit(status.code().unwrap_or(1)),
78:         Err(e) => fail(&format!("spawn failed: {e}")),
79:     }
80: }
