1: //! Linux-only Landlock filesystem ruleset for the `exec` role (P5-T1).
2: //!
3: //! This whole module is gated behind `#[cfg(target_os = "linux")]` at its
4: //! declaration site (`exec/mod.rs`), so the `landlock` crate is only pulled in
5: //! on Linux and the rest of the crate compiles unchanged on macOS/Windows.
6: //!
7: //! The ruleset is applied to the CURRENT process BEFORE it `exec`s the target
8: //! (the restrictions are inherited across `exec`; see [`super::runner`]). We
9: //! use the widest-supported ABI (`ABI::V1`, read+write) for maximum kernel
10: //! compatibility in this first slice.
11: 
12: use std::fmt;
13: 
14: use landlock::{
15:     Access, AccessFs, PathBeneath, PathFd, Ruleset, RulesetAttr, RulesetCreatedAttr, RulesetError,
16:     RulesetStatus, ABI,
17: };
18: 
19: use super::plan::ExecPlan;
20: 
21: /// A hard configuration error building/applying the Landlock ruleset.
22: ///
23: /// A kernel that simply lacks Landlock support is NOT an error — that case is
24: /// reported as `Ok(false)` (degraded) by [`apply_fs_ruleset`]. These variants
25: /// only cover genuine misconfiguration (a missing allow path, or a ruleset
26: /// syscall failure) so the caller never silently runs weaker than requested.
27: #[derive(Debug)]
28: pub enum LandlockError {
29:     /// A ruleset builder/syscall error from the `landlock` crate.
30:     Ruleset(RulesetError),
31:     /// An allow path could not be opened (e.g. it does not exist).
32:     PathFd { path: String, source: String },
33: }
34: 
35: impl fmt::Display for LandlockError {
36:     fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
37:         match self {
38:             LandlockError::Ruleset(e) => write!(f, "landlock ruleset error: {e}"),
39:             LandlockError::PathFd { path, source } => {
40:                 write!(f, "cannot open allow path {path:?}: {source}")
41:             }
42:         }
43:     }
44: }
45: 
46: impl std::error::Error for LandlockError {}
47: 
48: impl From<RulesetError> for LandlockError {
49:     fn from(e: RulesetError) -> Self {
50:         LandlockError::Ruleset(e)
51:     }
52: }
53: 
54: /// Apply the filesystem ruleset described by `plan` to the current process.
55: ///
56: /// Returns:
57: /// - `Ok(true)`  — ruleset enforced (fully or partially) by the kernel.
58: /// - `Ok(false)` — kernel lacks Landlock support; enforcement degraded (NOT an
59: ///   error: the caller proceeds with `landlock:false, degraded:true`).
60: /// - `Err(_)`    — hard configuration error (missing allow path or syscall
61: ///   failure).
62: pub fn apply_fs_ruleset(plan: &ExecPlan) -> Result<bool, LandlockError> {
63:     let abi = ABI::V1;
64: 
65:     let mut ruleset = Ruleset::default()
66:         .handle_access(AccessFs::from_all(abi))?
67:         .create()?;
68: 
69:     for path in &plan.allow_read {
70:         let fd = PathFd::new(path).map_err(|source| LandlockError::PathFd {
71:             path: path.clone(),
72:             source: source.to_string(),
73:         })?;
74:         ruleset = ruleset.add_rule(PathBeneath::new(fd, AccessFs::from_read(abi)))?;
75:     }
76: 
77:     for path in &plan.allow_write {
78:         let fd = PathFd::new(path).map_err(|source| LandlockError::PathFd {
79:             path: path.clone(),
80:             source: source.to_string(),
81:         })?;
82:         ruleset = ruleset.add_rule(PathBeneath::new(fd, AccessFs::from_all(abi)))?;
83:     }
84: 
85:     let status = ruleset.restrict_self()?;
86:     Ok(!matches!(status.ruleset, RulesetStatus::NotEnforced))
87: }
